    // ================================================================================================
    // Unscented Kalman Filter (UKF): Van der Merwe scaled sigma points + the unscented transform, over
    // the SAME IfloatKFModel/IfloatKFMeasurement functors ekfPredict/ekfUpdate use -- but calling
    // ONLY F/H (JacobianF/JacobianH are never read; no linearization at all is the whole point).
    //
    // Algorithm reference: FilterPy (rlabbe/filterpy, MIT) -- MerweScaledSigmaPoints and
    // UnscentedKalmanFilter's predict/update recombination. Two deliberate deviations from it:
    // sigma points are regenerated FRESH at the start of BOTH ukfPredict and ukfUpdate (see
    // GenerateSigmaPoints), and alpha defaults to 1, not the classic ~1e-3 (see floatUKFCache).
    //
    // The sigma-point spread uses CHOP (rank-revealing pivoted Cholesky), not a plain Cholesky: a
    // rank-deficient or Indefinite P degrades to a DEGENERATE (duplicated-at-the-mean) sigma spread
    // along the null directions instead of FilterPy's hard failure.
    //
    // Wc[0] can be NEGATIVE (alpha < 1) -- the classic scaled-UKF pitfall, since the recombined
    // covariance is a WEIGHTED SUM of outer products, not a Joseph-form product guaranteed PSD
    // regardless of gain. Both ukfPredict and ukfUpdate symmetrize explicitly; this library's default
    // alpha=1 keeps Wc[0] non-negative for kappa=0, but a caller-chosen smaller alpha can still drive
    // the recombination indefinite in principle (mitigated, not eliminated, by the defaults).
    // ================================================================================================
    public static partial class Kalman
    {
        // Regenerates cache.X (the (2n+1) x n sigma points) from the CURRENT (x, P), via CHOP's
        // pivoted Cholesky. CHOP factors P^T·P_cov·P = L·Lᵀ (P_cov the covariance, P the pivot
        // permutation -- unfortunate letter clash with the state covariance, disambiguated here as
        // "the permutation" everywhere else): the sigma-spread vectors are the COLUMNS of the
        // UNPERMUTED factor, i.e. column k of L scattered back through the permutation
        // (v[Piv[i]] = L[i,k]) -- L's own columns are in PIVOTED order, not the original one.
        //
        // On CHOP.Indefinite (P not even PSD -- a numerically broken covariance), every sigma point
        // collapses to the mean (v = 0) rather than reading L's undefined contents; on a rank-
        // deficient PSD P, CHOP's own contract already zero-fills L's columns past the detected rank,
        // so the same "collapse to the mean" degeneracy falls out for those columns with no special
        // casing here.
        //
        // Called FRESH at the start of BOTH ukfPredict and ukfUpdate, so ukfUpdate is safe to call
        // more than once per ukfPredict (the multi-sensor-fusion pattern Kalman.update supports), at
        // the cost of one extra Cholesky per call.
        static void GenerateSigmaPoints(in floatN x, in floatMxN P, ref floatUKFCache cache)
        {
            int n = cache.N;
            var rinfo = CHOP.decomp(in P, ref cache.L, ref cache.Piv, ref cache.chopWs);
            bool solved = rinfo.Solved;
            float scale = math.sqrt((float)n + cache.lambda);

            for (int i = 0; i < n; i++) cache.X[0, i] = x[i];

            for (int k = 0; k < n; k++)
            {
                for (int i = 0; i < n; i++) cache.diff[i] = 0;
                if (solved)
                {
                    for (int i = 0; i < n; i++)
                        cache.diff[cache.Piv[i]] = cache.L[i, k] * scale;
                }
                for (int i = 0; i < n; i++)
                {
                    float d = cache.diff[i];
                    cache.X[k + 1, i] = x[i] + d;
                    cache.X[n + k + 1, i] = x[i] - d;
                }
            }
        }

        /// <summary>
        /// UKF predict: regenerates sigma points from (x, P) (see <see cref="GenerateSigmaPoints"/>),
        /// propagates each through <c>model.F</c> (JacobianF is never called), then sets x/P to the
        /// weighted mean/covariance (+ Q, symmetrized) of the propagated points. Zero
        /// <c>Allocator.Temp</c> use -- every intermediate is a field of <paramref name="cache"/>.
        /// </summary>
        /// <param name="s">Must be constructed via <c>new floatKFState(n, mMax, allocator)</c>.</param>
        /// <param name="cache">Must be constructed via <c>new floatUKFCache(n, ...)</c> for the SAME n.</param>
        /// <param name="Q">Process noise covariance, n x n.</param>
        public static void ukfPredict<TModel>(ref floatKFState s, ref floatUKFCache cache,
                                              in TModel model, in floatN u, in floatMxN Q)
            where TModel : struct, IfloatKFModel
        {
            if (!s.IsCreated)
                throw new ArgumentException("Kalman.ukfPredict: state must be constructed via new floatKFState(n, mMax, allocator)");
            if (!cache.IsValid(s.N))
                throw new ArgumentException("Kalman.ukfPredict: cache must be constructed via new floatUKFCache(n, ...) matching state dimension");
            if (!Q.IsSquare || Q.M_Rows != s.N)
                throw new ArgumentException("Kalman.ukfPredict: Q must be n x n");

            int n = s.N;
            int npts = 2 * n + 1;

            GenerateSigmaPoints(in s.x, in s.P, ref cache);

            for (int k = 0; k < npts; k++)
            {
                for (int i = 0; i < n; i++) cache.rowIn[i] = cache.X[k, i];
                model.F(in cache.rowIn, in u, ref cache.rowOut);
                for (int i = 0; i < n; i++) cache.Y[k, i] = cache.rowOut[i];
            }

            for (int i = 0; i < n; i++) cache.xPred[i] = 0;
            for (int k = 0; k < npts; k++)
            {
                float w = cache.Wm[k];
                for (int i = 0; i < n; i++) cache.xPred[i] += w * cache.Y[k, i];
            }

            // Pacc = Σ Wc[k]·d_k·d_kᵀ as ONE symmetric GEMM instead of npts rank-1 scalar updates:
            // D = Y − 1·xPredᵀ (overwrites Y — its propagated points are fully consumed above),
            // WD = Wc-row-scaled D (reuses X — its sigma points are fully consumed above), then
            // Pacc = (WD)ᵀ·D, symmetric by construction (dotSym zero-clears Pacc itself).
            for (int k = 0; k < npts; k++)
            {
                float w = cache.Wc[k];
                for (int i = 0; i < n; i++)
                {
                    float d = cache.Y[k, i] - cache.xPred[i];
                    cache.Y[k, i] = d;
                    cache.X[k, i] = w * d;
                }
            }
            Blas.dotSym(in cache.X, in cache.Y, ref cache.Pacc);
            cache.Pacc.addInPlace(Q);
            Riccati.SymmetrizeInPlace(ref cache.Pacc);

            s.x.CopyFrom(in cache.xPred);
            s.P.CopyFrom(in cache.Pacc);
        }

        /// <summary>
        /// UKF update: regenerates sigma points from the CURRENT (x, P) (see
        /// <see cref="GenerateSigmaPoints"/> for why this is fresh, not reused from the last
        /// <c>ukfPredict</c>), propagates each through <c>meas.H</c> (JacobianH is never called),
        /// forms the innovation covariance Pzz = Σ Wc·outer(dz,dz) + R and cross-covariance
        /// Pxz = Σ Wc·outer(dx,dz), solves K = Pxz·Pzz⁻¹ via CHOP on the transposed system (never an
        /// explicit inverse), then x += Ky and P -= Pxz·Kᵀ (symmetrized). Allocates small
        /// <c>Allocator.Temp</c> scratch sized to <c>z.N</c> (arbitrary per call, same convention as
        /// <see cref="update"/>). On Pzz not even PSD (Indefinite), x/P are left UNCHANGED and
        /// <see cref="KFStatus.InnovationSolveFailed"/> is reported.
        /// </summary>
        /// <param name="R">Measurement noise covariance, m x m (m = z.N).</param>
        public static KFInfo ukfUpdate<TMeas>(ref floatKFState s, ref floatUKFCache cache,
                                              in TMeas meas, in floatMxN R, in floatN z)
            where TMeas : struct, IfloatKFMeasurement
        {
            if (!s.IsCreated)
                throw new ArgumentException("Kalman.ukfUpdate: state must be constructed via new floatKFState(n, mMax, allocator)");
            if (!cache.IsValid(s.N))
                throw new ArgumentException("Kalman.ukfUpdate: cache must be constructed via new floatUKFCache(n, ...) matching state dimension");
            int m = z.N;
            if (!R.IsSquare || R.M_Rows != m)
                throw new ArgumentException("Kalman.ukfUpdate: R must be m x m (m = z.N)");

            int n = s.N;
            int npts = 2 * n + 1;

            GenerateSigmaPoints(in s.x, in s.P, ref cache);

            var zRow = new floatN(m, Allocator.Temp);
            var Z = new floatMxN(npts, m, Allocator.Temp);
            for (int k = 0; k < npts; k++)
            {
                for (int i = 0; i < n; i++) cache.rowIn[i] = cache.X[k, i];
                meas.H(in cache.rowIn, ref zRow);
                for (int j = 0; j < m; j++) Z[k, j] = zRow[j];
            }
            zRow.Dispose();

            var zPred = new floatN(m, Allocator.Temp);
            for (int j = 0; j < m; j++) zPred[j] = 0;
            for (int k = 0; k < npts; k++)
            {
                float w = cache.Wm[k];
                for (int j = 0; j < m; j++) zPred[j] += w * Z[k, j];
            }

            var Pzz = new floatMxN(m, m, Allocator.Temp);
            var Pxz = new floatMxN(n, m, Allocator.Temp);

            // Pzz = Σ Wc·dz·dzᵀ and Pxz = Σ Wc·dx·dzᵀ as GEMMs instead of npts rank-1 scalar
            // updates: dX = X − 1·xᵀ (overwrites X — its sigma points are fully consumed by the
            // measurement loop above), dZ = Z − 1·zPredᵀ (in place), WdZ = Wc-row-scaled dZ.
            // Pzz = dZᵀ·(WdZ) is symmetric by construction; Pxz = dXᵀ·(WdZ). Both dot forms
            // zero-clear their destination.
            var WdZ = new floatMxN(npts, m, Allocator.Temp);
            for (int k = 0; k < npts; k++)
            {
                float w = cache.Wc[k];
                for (int i = 0; i < n; i++) cache.X[k, i] -= s.x[i];
                for (int j = 0; j < m; j++)
                {
                    float d = Z[k, j] - zPred[j];
                    Z[k, j] = d;
                    WdZ[k, j] = w * d;
                }
            }
            Blas.dotSym(in Z, in WdZ, ref Pzz);
            Blas.dot(in cache.X, in WdZ, ref Pxz, transposeA: true);
            WdZ.Dispose();
            Pzz.addInPlace(R);
            Riccati.SymmetrizeInPlace(ref Pzz);

            var y = new floatN(m, Allocator.Temp);
            y.CopyFrom(in z);
            y.addScaledInPlace((float)(-1), zPred);
            double innovationNorm = math.sqrt((double)Blas.dot(y, y));

            var Pxzt = new floatMxN(m, n, Allocator.Temp);
            Blas.trans(in Pxz, ref Pxzt);

            var L = new floatMxN(m, m, Allocator.Temp);
            var Piv = new Pivot(m, Allocator.Temp);
            var rinfo = CHOP.decomp(in Pzz, ref L, ref Piv);

            KFStatus status;
            if (rinfo.Solved)
            {
                CHOP.decompSolve(ref L, in Piv, rinfo.rank, ref Pxzt);   // Pxzt := Pzz^-1 Pxzᵀ = Kᵀ

                var Ky = new floatN(n, Allocator.Temp);
                Blas.dot(in y, in Pxzt, ref Ky);   // Ky = Pxztᵀ y = K y (K never materialized)
                s.x.addScaledInPlace((float)1, Ky);

                var PxzK = new floatMxN(n, n, Allocator.Temp);
                Blas.dot(in Pxz, in Pxzt, ref PxzK);   // Pxz * Kᵀ (Pxzt == Kᵀ)
                s.P.subInPlace(PxzK);
                Riccati.SymmetrizeInPlace(ref s.P);

                status = KFStatus.Ok;

                Ky.Dispose(); PxzK.Dispose();
            }
            else
            {
                status = KFStatus.InnovationSolveFailed;
            }

            L.Dispose(); Piv.Dispose(); Pxzt.Dispose(); y.Dispose();
            Pzz.Dispose(); Pxz.Dispose(); zPred.Dispose(); Z.Dispose();

            return new KFInfo { status = status, innovationNorm = innovationNorm };
        }
    }
